class CPU {
  constructor(opts = {}) {
    this.path = 'cache/sli/GPU/sli/RAM/sli';
    this.sli = ['GPU', 'RAM', 'CPU', 'tmp'];
    this.hdf = {
      d: 'd.hdf.rom', e: 'e.hdf.rom', i: 'i.hdf.rom',
      n: 'n.hdf.rom', o: 'o.hdf.rom', r: 'r.hdf.rom',
      s: 's.hdf.rom', u: 'u.hdf.rom', w: 'w.hdf.rom'
    };
    this.ready = {
      sli: 'sli.ready',
      healt: 'healt.room.ready',
      hdf: 'hdf.ready',
      cache: 'cache.ready'
    };
    this.tmp = {
      live: 'Live.tmp',
      real: 'REAL.tmp',
      zone: 'ZONE.tmp',
      pover: 'pover.tmp',
      sli_pover: 'sli.pover'
    };
    this.score = {
      score: '81.score.js',
      viewer: '81.viewer.js',
      tmp: '81.tmp'
    };
    this.units = {
      gpu: { id: 'GPU.seed', power: 0, active: false, sli: 'GPU/sli' },
      ram: { id: 'RAM.seed', power: 0, active: false, sli: 'RAM/sli' },
      cpu: { id: 'cpu.unit', power: 0, active: false, sli: 'CPU/sli' }
    };
    this.state = {
      loopBroken: false,
      loopCount: 0,
      power: 'sli.pover',
      wonderius: null,
      continuum: null,
      quantTriangle: null,
      score: 0
    };
    this._listeners = new Map();
    this._interval = null;
    this.opts = opts;
  }
  // ─── WONDERIUS ASSEMBLER ──────────────────────────────────
  // d,e,i,n,o,r,s,u,w -> W O N D E R I U S
  // hdf.rom Fragmente sind cyan, cpu.js ist gold - GANZ
  assembleWonderius() {
    // Original Order aus Repo: d,e,i,n,o,r,s,u,w
    // Ziel: WONDERIUS (W-O-N-D-E-R-I-U-S)
    const order = ['w','o','n','d','e','r','i','u','s'];
    const fragments = order.map(k => {
      const file = this.hdf[k];
      // In echt: fetch(file) + parse, hier Symbol
      return { key: k, file, char: k.toUpperCase(), loaded: true };
    });
    const assembled = fragments.map(f => f.char).join(''); // WONDERIUS
    this.state.wonderius = {
      raw: Object.keys(this.hdf).sort().join(''), // deinorsuw
      sorted: 'deinorsuw',
      assembled, // WONDERIUS
      fragments,
      timestamp: Date.now(),
      complete: true
    };
    
    this.emit('wonderius', this.state.wonderius);
    return this.state.wonderius;
  }
  // ─── CONTINUUM-REALITY LOADER ─────────────────────────────
  async loadContinuum(json = null) {
    // continuum-reality.json + quant-triangle-analysis.json
    const continuum = json || await this._fetchJson('continuum-reality.json')
      .catch(() => ({
        version: '1.0.3',
        reality: 'continuum',
        axioms: ['a.real', 'b.tmp', 'c.zone'],
        state: 'REAL.tmp | Live.tmp | ZONE.tmp'
      }));
    
    const quant = await this._fetchJson('quant-triangle-analysis.json')
      .catch(() => ({
        triangles: 81,
        score: '81.score.js',
        analysis: { a: 'b', b: 't', c: 'h' },
        depth: 3
      }));
    this.state.continuum = continuum;
    this.state.quantTriangle = quant;
    this.emit('continuum', { continuum, quant });
    return { continuum, quant };
  }
  // ─── AGGREGATOR ───────────────────────────────────────────
  // Merges continuum-reality.json + all hdf.rom
  aggregator() {
    if (!this.state.wonderius) this.assembleWonderius();
    if (!this.state.continuum) {
      // sync fallback
      this.state.continuum = { version: '1.0.3', fallback: true };
    }
    const aggregated = {
      wonderius: this.state.wonderius.assembled,
      hdf: this.hdf,
      continuum: this.state.continuum,
      quant: this.state.quantTriangle,
      sli: this.sli,
      tmp: this.tmp,
      path: this.path,
      hash: this._hash(this.state.wonderius.assembled + this.path)
    };
    this.emit('aggregated', aggregated);
    return aggregated;
  }
  // ─── AXIOM.MAP LOADER ─────────────────────────────────────
  axiomMapLoader(mapPath = 'axiom.map.js') {
    // Lädt axiom.map.js - Abbildung sli -> real
    const map = {
      'GPU/sli': 'gpu.unit -> 81.score',
      'RAM/sli': 'ram.unit -> Live.tmp',
      'CPU/sli': 'cpu.unit -> REAL.tmp',
      'cache/sli': 'cache.ready -> ZONE.tmp',
      'sli.pover': this.state.power
    };
    this.emit('axiom', map);
    return map;
  }
  // ─── QUANT TRIANGLE ANALYSIS ──────────────────────────────
  quantTriangleAnalysis() {
    // Analysiert quant-triangle-analysis.json
    // 3 Achsen: b, h, t (Breite, Hoch, Tiefe)
    // 81.score.js handling
    const triangles = [];
    for (let i = 0; i < 81; i++) {
      triangles.push({
        id: i,
        b: Math.random(),
        h: Math.random(),
        t: Math.random(),
        score: Math.floor(Math.random() * 81),
        tmp: i % 3 === 0 ? 'Live.tmp' : i % 3 === 1 ? 'REAL.tmp' : 'ZONE.tmp'
      });
    }
    const score = triangles.reduce((a, t) => a + t.score, 0) / triangles.length;
    this.state.score = score;
    return { triangles, avgScore: score, viewer: this.score.viewer };
  }
  // ─── SLI LOOP BREAKER ─────────────────────────────────────
  // Das ist der Kern: bricht recursive cache/sli/GPU/sli/RAM/sli/...
  breakSliLoop() {
    if (this.state.loopBroken) return { already: true, loopCount: this.state.loopCount };
    
    // Erkenne Loop: path enthält sich selbst
    const depth = (this.path.match(/sli/g) || []).length;
    this.state.loopCount = depth;
    
    // BREAK: Setze festen Anker statt Rekursion
    const anchor = 'cache/sli/cpu.js::WONDERIUS_ANCHOR';
    this.path = anchor;
    this.state.loopBroken = true;
    
    // Power Management
    this.setPower('sli.pover::BROKEN::cpu.js');
    
    // Alle Units auf READY
    Object.keys(this.units).forEach(k => {
      this.units[k].active = true;
      this.units[k].power = 100;
    });
    this.emit('loop-broken', { anchor, depth, timestamp: Date.now() });
    return { broken: true, anchor, depth };
  }
  // ─── POWER MANAGEMENT ─────────────────────────────────────
  setPower(state) {
    // sli.pover + pover.tmp handling
    this.state.power = state;
    this.tmp.pover = state;
    this.tmp.sli_pover = state;
    this.emit('power', state);
    return state;
  }
  sliReadyCheck() {
    // Prüft sli.ready, healt.room.ready, hdf.ready, cache.ready
    const checks = {};
    Object.entries(this.ready).forEach(([k, file]) => {
      checks[k] = { file, ready: this.state.loopBroken || k === 'cache' };
    });
    const allReady = Object.values(checks).every(c => c.ready);
    return { checks, allReady, pover: this.state.power };
  }
  // ─── 81 SCORE SYSTEM ──────────────────────────────────────
  handle81Score() {
    // 81.score.js, 81.tmp, Live.tmp, REAL.tmp, ZONE.tmp
    const scores = {
      '81.score.js': this.state.score,
      '81.tmp': this.state.score * 0.81,
      'Live.tmp': Math.random() > 0.5 ? 'ACTIVE' : 'PENDING',
      'REAL.tmp': 'REAL',
      'ZONE.tmp': 'ZONE-' + Math.floor(Math.random() * 3)
    };
    return scores;
  }
  // ─── CTRL INTERFACE (für ctrl.ler) ────────────────────────
  ctrl(cmd, payload = {}) {
    switch(cmd) {
      case 'start': return this.start();
      case 'stop': return this.stop();
      case 'assemble': return this.assembleWonderius();
      case 'break-loop': return this.breakSliLoop();
      case 'load-continuum': return this.loadContinuum(payload);
      case 'aggregate': return this.aggregator();
      case 'axiom': return this.axiomMapLoader();
      case 'quant': return this.quantTriangleAnalysis();
      case 'power': return this.setPower(payload.state);
      case 'ready': return this.sliReadyCheck();
      case 'score': return this.handle81Score();
      case 'status': return this.getStatus();
      default: return { error: 'unknown ctrl: ' + cmd, available: ['start','stop','assemble','break-loop','load-continuum','aggregate','axiom','quant','power','ready','score','status'] };
    }
  }
  // ─── LIFECYCLE ────────────────────────────────────────────
  start() {
    if (this._interval) return { already: true };
    this._interval = setInterval(() => {
      if (!this.state.loopBroken) this.state.loopCount++;
      this.emit('tick', { loopCount: this.state.loopCount, power: this.state.power });
    }, 760);
    this.emit('started', Date.now());
    return { started: true };
  }
  stop() {
    if (this._interval) clearInterval(this._interval);
    this._interval = null;
    this.emit('stopped', Date.now());
    return { stopped: true };
  }
  getStatus() {
    return {
      path: this.path,
      wonderius: this.state.wonderius,
      loopBroken: this.state.loopBroken,
      loopCount: this.state.loopCount,
      power: this.state.power,
      units: this.units,
      ready: this.sliReadyCheck(),
      score: this.handle81Score()
    };
  }
  // ─── EVENT SYSTEM ─────────────────────────────────────────
  on(event, fn) {
    if (!this._listeners.has(event)) this._listeners.set(event, []);
    this._listeners.get(event).push(fn);
  }
  emit(event, data) {
    (this._listeners.get(event) || []).forEach(fn => fn(data));
  }
  // ─── UTILS ────────────────────────────────────────────────
  async _fetchJson(path) {
    const r = await fetch(path);
    if (!r.ok) throw new Error('not found: ' + path);
    return r.json();
  }
  _hash(str) {
    let h = 0;
    for (let i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) | 0;
    return h.toString(16);
  }
}
// Export für ctrl.ler + Module
if (typeof window !== 'undefined') {
  window.CPU = CPU;
  window.cpu = window.cpu || new CPU();
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { CPU };
}
